__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["content"] = function(...)
-- =====================================================================
-- Lib: chapter-text cleanup shared by the novel extractors.
-- Loaded via require_lib("content"). No dependencies on other libs.
--
-- Engine API used inside the functions only: string_normalize,
-- regex_replace, string_trim (all guarded, so the module still loads
-- outside the app).
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Chapter-heading prefix that gets stripped when it duplicates the
-- chapter title the engine already shows (guide:823). Language picks the
-- word for the ordinal; unknown/missing lang falls back to the dominant
-- ru/en cluster (Глава N | Chapter N).
local HEAD_BY_LANG = {
    ru = "(Глава\\s+\\d+|Chapter\\s+\\d+)",
    en = "(Chapter\\s+\\d+)",
    zh = "(第[\\d一二三四五六七八九十百]+[章节卷回部集篇]|Chapter\\s+\\d+)",
    ja = "(第\\s*\\d+話|Chapter\\s+\\d+)",
    id = "(Bab\\s+\\d+|Chapter\\s+\\d+)",
}

-- Credit lines: the English set is in every copy that has a credits
-- step at all; the per-language set is the union of the ru (ru/bookhamster,
-- ru/ifreedom, ru/jaomix), zh (zh/twkan, zh/sto9) and id (id/indowebnovel)
-- variants. Both are applied for the chosen language.
local CREDITS_EN =
    "(?im)^\\s*(Translator|Editor|Proofreader|Read\\s+(at|on|latest))[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)"

local CREDITS_BY_LANG = {
    ru = "(?im)^\\s*(Перевод|Переводчик|Редакция|Редактор|Аннотация|Сайт|Источник|Студия)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
    zh = "(?im)^\\s*(翻译|譯者|译者|編輯|编辑|校對|校对|更新|閱讀|阅读|最新閱讀|最新阅读)[:\\s：][^\\n\\r]{0,70}(\\r?\\n|$)",
    id = "(?im)^\\s*(Penerjemah|Editor|Proofreader|Baca\\s+(di|novel|lanjutan)|Sumber|Donasi|Trakteer)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
}

-- Escape regex metacharacters of a literal chapter title or domain
-- (Java/Kotlin regex syntax: backslash-escape, not %-escape).
local function escapeLiteral(s)
    return (s:gsub("[%.%+%-%*%?%[%]%(%){}%$%^%|%%]", "\\%1"))
end

-- applyStandardContentTransforms (guide:812) as a shared function.
--   opts.domain      — baseUrl (or a bare host): lines mentioning it are dropped;
--   opts.chapterTitle — literal title to strip instead of the "Глава/Chapter N"
--                      prefix (duplicates the title field of the chapter);
--   opts.lang        — "ru" (default) / "en" / "zh" / "ja" / "id": picks the
--                      chapter-heading word and the extra credit lines.
-- Returns "" for an empty input, as every copy does.
function M.standardTransforms(text, opts)
    if not text or text == "" then return "" end
    opts = opts or {}
    local lang = opts.lang or "ru"

    if type(string_normalize) == "function" then
        text = string_normalize(text)
    end

    if type(regex_replace) ~= "function" then
        logErr("meta/content: regex_replace unavailable, transforms skipped")
        return trim(text)
    end

    -- 1. lines linking back to the source site (watermarks, "read more")
    local domain = opts.domain
    if type(domain) == "string" and domain ~= "" then
        domain = domain:gsub("https?://", ""):gsub("^www%.", ""):gsub("/$", "")
        if domain ~= "" then
            text = regex_replace(text, "(?i)" .. escapeLiteral(domain) .. ".*?\\n", "")
        end
    end

    -- 2. leading chapter heading, duplicated in the title field
    local head = opts.chapterTitle
        and ("(" .. escapeLiteral(opts.chapterTitle) .. ")")
        or HEAD_BY_LANG[lang] or HEAD_BY_LANG.ru
    text = regex_replace(text, "(?i)\\A[\\s\\p{Z}\\uFEFF]*(" .. head .. "[^\\n\\r]*[\\n\\r\\s]*)+", "")

    -- 3. translator / editor / "read at" credit lines
    text = regex_replace(text, CREDITS_EN, "")
    local credits = CREDITS_BY_LANG[lang]
    if credits then text = regex_replace(text, credits, "") end

    -- 4. trim (string_trim collapses nothing but the edges, as in the copies)
    if type(string_trim) == "function" then
        return string_trim(text)
    end
    return trim(text)
end

return M
end

__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["gdriveplayer"] = function(...)
-- =====================================================================
-- Lib: gdriveplayer resolver — embed2.php serves a page whose inline
--      script body is atob()'ed and XOR-encrypted with the key from
--      `var k="..."`; the decrypted JS carries a relative HLS path
--      HLS="hlsplaylist.php?s=…&idhls=….m3u8" — a media playlist with
--      direct segments on a third-party CDN.
-- From one copy: id/animexin.lua:568-617 (resolveGdriveplayer + bxor8).
-- Loaded via require_lib("gdriveplayer"). No dependencies on other libs.
--
-- Pure decode: the caller does the batch GET (Referer = embed origin);
-- logging stays with the caller. base64_decode is engine API («Тяжёлые
-- операции»); the XOR loop stays in Lua — it runs over one short script.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- XOR of two bytes, bit by bit (sandbox is Lua 5.1 — no bitwise ops).
local function bxor8(a, b)
    local r, p = 0, 1
    for _ = 1, 8 do
        local ab, bb = a % 2, b % 2
        if ab ~= bb then r = r + p end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        p = p * 2
    end
    return r
end

-- body — the embed2.php page; origin — "scheme://host/" of the embed
-- (used to absolutise a relative HLS path).
-- Returns a list of { url, mime = "hls" } or nil + reason:
-- "no key/atob in embed" | "atob did not decode" | "HLS= not found after decrypt".
function M.decode(body, origin)
    if type(body) ~= "string" then return nil, "no key/atob in embed" end
    local key = body:match('var k="([^"]+)"')
    local blob = body:match('atob%("([^"]+)"%)')
    if not key or not blob or #key == 0 then
        return nil, "no key/atob in embed"
    end
    local raw = base64_decode(blob)
    if type(raw) ~= "string" or raw == "" then
        return nil, "atob did not decode"
    end
    local chars = {}
    local klen = #key
    for i = 1, #raw do
        chars[i] = string.char(bxor8(raw:byte(i), key:byte((i - 1) % klen + 1)))
    end
    local decoded = table.concat(chars)
    local hls = decoded:match('HLS="([^"]+)"')
    if not hls then return nil, "HLS= not found after decrypt" end
    hls = hls:gsub("\\/", "/")
    if hls:sub(1, 2) == "//" then
        hls = "https:" .. hls
    elseif hls:sub(1, 1) == "/" then
        hls = origin .. hls
    else
        hls = origin .. "/" .. hls
    end
    return { { url = hls, mime = "hls" } }
end

return M
end

__LOADERS["hls"] = function(...)
-- =====================================================================
-- Lib: stream helpers for videohost extractors: pickStream (generic
--      m3u8/mp4 scan) + hasMediaExt (mime typing of extension-less URLs).
-- Loaded via require_lib("hls"); uses require_lib("urls").
-- =====================================================================
local version = "1.0.0"

local urls = require_lib("urls")

local M = {}

-- =====================================================================
-- Generic stream scan
-- =====================================================================

function M.pickStream(t, embedUrl)
    -- 1) absolute URL
    local hls = t:match([=[(https?://[^"'%s\<>]+%.m3u8[^"'%s\<>]*)]=])
    if hls then return hls, "hls" end

    -- 2) quoted, relative or protocol-relative
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "([^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".m3u8", 1, true) then
                return urls.resolve(s, embedUrl), "hls"
            end
        end
    end

    -- 3) direct mp4
    local mp4 = t:match([=[(https?://[^"'%s\<>]+%.mp4[^"'%s\<>]*)]=])
    if mp4 then return mp4, "mp4" end
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "(//[^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".mp4", 1, true) then
                return urls.resolve(s, embedUrl), "mp4"
            end
        end
    end
    return nil, nil
end

-- =====================================================================
-- Media extension check
-- =====================================================================

-- Does the URL path (before "?" / "#") end with a media extension?
-- Without it media3 types the stream as progressive and fails on an HLS
-- body (rationale: ar/anime4up.lua:328). Union of the three plugin copies
-- (ar/anime4up.lua:330, ar/animephoenix.lua:45, ar/witanime.lua:1958):
-- .mkv comes from animephoenix and is progressive too, so it must not be
-- typed as "hls".
function M.hasMediaExt(u)
    local base = u:match("^[^%?#]*") or u
    return base:match("%.m3u8$") ~= nil
        or base:match("%.mp4$") ~= nil
        or base:match("%.mkv$") ~= nil
end

return M
end

__LOADERS["okru"] = function(...)
-- =====================================================================
-- Lib: ok.ru resolver — data-options (entity-encoded) -> JSON ->
--      flashvars.metadata -> stream candidates.
-- Merged from five copies: ar/anime4up.lua:662, ar/animephoenix.lua:849,
-- ar/witanime.lua:1536, id/anichin.lua:471, id/animexin.lua:484.
-- Loaded via require_lib("okru"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

local OKRU_REFERER = "https://ok.ru/"

-- body — the ok.ru player page. The caller does the http_get (four of the
-- five copies receive the body from a batch; ar/witanime.lua:1536 fetches
-- the page itself and keeps doing that on its side).
-- Returns a list of { url, mime, name?, referer }; empty list when nothing
-- was parsed. Logging is plugin-specific and stays with the caller.
function M.resolveOkRu(body)
    if type(body) ~= "string" then return {} end
    -- Stub instead of the player: video removed or geo-blocked. Not a
    -- parser failure, so log it explicitly and bail out early.
    if body:find("vp_video_stub", 1, true) then
        log_error("ok.ru: video stub (removed or geo-blocked)")
        return {}
    end
    -- Primary: double quotes; fallback: single quotes.
    local opts = body:match('data%-options="([^"]+)"')
        or body:match("data%-options='([^']+)'")
    if not opts then
        log_error("ok.ru: no data-options, body len=" .. #body .. " head=" .. body:sub(1, 200))
        return {}
    end
    opts = opts:gsub("&quot;", '"'):gsub("&#39;", "'"):gsub("&lt;", "<")
        :gsub("&gt;", ">"):gsub("&amp;", "&")
    local ok, data = pcall(json_parse, opts)
    if not ok or type(data) ~= "table" or type(data.flashvars) ~= "table" then
        log_error("ok.ru: data-options parse failed, body len=" .. #body .. " opts=" .. opts:sub(1, 200))
        return {}
    end
    local meta = data.flashvars.metadata
    if type(meta) == "string" then
        local mok, m = pcall(json_parse, meta)
        meta = mok and type(m) == "table" and m or nil
    end
    if type(meta) ~= "table" then return {} end

    local out = {}
    -- The manifest URL carries no media extension: type it explicitly,
    -- otherwise media3 treats it as progressive (id/animexin.lua:482).
    if type(meta.hlsManifestUrl) == "string" and meta.hlsManifestUrl ~= "" then
        out[#out + 1] = {
            url = meta.hlsManifestUrl,
            mime = "hls",
            referer = OKRU_REFERER,
        }
    end
    -- videos[] are progressive renditions served without an extension.
    if type(meta.videos) == "table" then
        for _, v in ipairs(meta.videos) do
            local u = type(v) == "table" and v.url or nil
            if type(u) == "string" and u ~= "" then
                out[#out + 1] = {
                    url = u,
                    mime = "mp4",
                    name = type(v.name) == "string" and v.name or nil,
                    referer = OKRU_REFERER,
                }
            end
        end
    end
    return out
end

return M
end

__LOADERS["shared"] = function(...)
-- =====================================================================
-- Lib: 4shared — embed page -> direct link from the first <source src>.
-- Merged from two copies: ar/anime4up.lua:551-572 and ar/animephoenix.lua:
-- 772-790 (the <source> extraction was identical in both, only the wrapper
-- differed: a pushed candidate vs a URL list); both ports of
-- SharedExtractor.kt.
-- Loaded via require_lib("shared"). No dependencies on other libs.
--
-- The embed body is already in hand (both copies get it from their batch),
-- so there is no HTTP here; logging and the candidate shape stay with the
-- caller.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- Embed body + embed link -> absolute stream URL, or nil when there is
-- no <source>. The reference returns attr("src") as is; only
-- protocol-relative/relative values are absolutised, otherwise the player
-- will not open them.
function M.extract(body, embedUrl)
    if type(body) ~= "string" then return nil end
    local src = html_attr(body, "source", "src")
    if type(src) ~= "string" or src == "" then return nil end
    if not string_starts_with(src, "http") then
        if string_starts_with(src, "//") then
            src = "https:" .. src
        else
            src = url_resolve(embedUrl, src)
        end
    end
    return src
end

return M
end

__LOADERS["sources"] = function(...)
-- =====================================================================
-- Lib: stream-source helpers for videohost extractors: push (dedup by
--      url) + isSkipped (shared dead-host skip list) + hostLabel.
-- Loaded via require_lib("sources"); uses require_lib("urls").
-- =====================================================================
local version = "1.0.0"

local urls = require_lib("urls")

local M = {}

-- =====================================================================
-- Stream list dedup
-- =====================================================================

-- Append src to list unless its url was already seen. `seen` is a
-- url -> true table kept by the caller. Semantics are byte-identical to
-- the six inline copies (ar/witanime.lua:1331, ar/animephoenix.lua:656,
-- ar/anime4up.lua:357, ar/anime3rb.lua:402, ru/yummyanime.lua:515 and
-- the url-dedup core of pushCandidate in ar/anime4up.lua:547).
function M.push(list, seen, src)
    if type(src) ~= "table" then return end
    local url = src.url
    if type(url) ~= "string" or url == "" or seen[url] then return end
    seen[url] = true
    list[#list + 1] = src
end

-- Readable alias for migration of the pushSource-named copies.
M.pushSource = M.push

