-- Skip reason for a URL (or bare host), nil if the host is workable.
-- Call BEFORE any network request — that is the "hard timeout" for
-- known-dead hosts (same contract as the inline skipReason copies).
function M.isSkipped(url)
    if type(url) ~= "string" then return nil end
    local host = urls.hostOf(url)
    if host == "" then host = url:lower() end
    for _, s in ipairs(SKIP) do
        if host:find(s.sub, 1, true) then return s.reason end
    end
    return nil
end

-- Alias matching the inline function name used before migration.
M.skipReason = M.isSkipped

-- =====================================================================
-- Host label
-- =====================================================================

-- Display label for a hoster: host without the leading "www.", original
-- case kept (union of ar/animephoenix.lua:691 and ar/anime4up.lua:429 —
-- identical bodies). Distinct from urls.hostOf, which lowercases and is
-- meant for registry lookups, not UI.
function M.hostLabel(url)
    local host = (url or ""):match("^https?://([^/]+)") or url
    return (host or ""):gsub("^www%.", "")
end

return M
end

__LOADERS["uqload"] = function(...)
-- =====================================================================
-- Lib: uqload — embed (301 -> uqload.vc) -> packed-JS -> jwplayer sources.
-- Merged from two copies: ar/anime4up.lua:827-869 (packedMediaUrls,
-- resolveUqload; packedMediaUrls is also the parser of the vidmoly player
-- there) and ar/animephoenix.lua:792-827. packedMediaUrls was byte-identical
-- in both; resolveUqload differed only in the wrapper (pushed candidates vs
-- a URL list) and stays with the callers as a thin adapter.
-- Loaded via require_lib("uqload"); uses require_lib("hls") and engine
-- API unpack_packed ("" when there is no packer).
--
-- Live 2026-10-05: /embed-<id>.html serves an unpacked
-- jwplayer("vplayer").setup({sources:[{file:"…/master.m3u8?…"}]}).
-- The jwplayer config only exists unpacked, so a bare sources: pattern
-- over the body never matches; file:"…" also holds subs/logos, hence the
-- media-extension filter of the hls lib.
-- =====================================================================
local version = "1.0.0"

local hls = require_lib("hls")

local M = {}

-- Links to streams from the player body: unpacked text + original.
function M.packedMediaUrls(body)
    if type(body) ~= "string" then return {} end
    local text = body
    local un = unpack_packed(body)
    if un ~= "" then text = un .. "\n" .. body end
    local out, seen = {}, {}
    local function add(u)
        if seen[u] or not string_starts_with(u, "http") then return end
        if not hls.hasMediaExt(u) then return end
        seen[u] = true
        out[#out + 1] = u:gsub("\\/", "/"):gsub("&amp;", "&")
    end
    for u in text:gmatch('file:%s*"([^"]+)"') do add(u) end
    for u in text:gmatch("file:%s*'([^']+)'") do add(u) end
    for u in text:gmatch('"file"%s*:%s*"([^"]+)"') do add(u) end
    for u in text:gmatch([[https?://[^"'%s<>\\]+%.m3u8[^"'%s<>\\]*]]) do add(u) end
    for u in text:gmatch([[https?://[^"'%s<>\\]+%.mp4[^"'%s<>\\]*]]) do add(u) end
    return out
end

-- Embed body -> list of stream URLs, or nil + reason when the packed-JS
-- holds no media (caller logs with its own prefix).
function M.resolve(body)
    local urls = M.packedMediaUrls(body)
    if #urls == 0 then return nil, "no sources in packed-JS" end
    return urls
end

return M
end

__LOADERS["urls"] = function(...)
-- =====================================================================
-- Lib: shared URL helpers (origin, unescapeSlashes, hostOf, resolve,
--      absUrl, driveDirectUrl) for videohost and novel extractors.
-- Loaded via require_lib("urls"). No dependencies on other libs.
-- =====================================================================
local version = "1.2.0"

local M = {}

-- =====================================================================
-- URL helpers
-- =====================================================================

function M.origin(url)
    local scheme, host = url:match("^(https?)://([^/?#]+)")
    if not scheme then return nil end
    return scheme .. "://" .. host .. "/"
end

function M.unescapeSlashes(s)
    local r = s:gsub("\\/", "/")
    r = r:gsub("\\u0026", "&")
    return r
end

function M.hostOf(url)
    return ((url or ""):match("^https?://([^/?#:]+)") or ""):lower()
end

-- Relative / protocol-relative URL -> absolute (relative to the embed).
function M.resolve(u, embedUrl)
    u = M.unescapeSlashes(u)
    if u:sub(1, 2) == "//" then return "https:" .. u end
    if u:find("^https?://") then return u end
    local o = M.origin(embedUrl or "")
    if o then
        o = o:gsub("/$", "")
        return o .. (u:sub(1, 1) == "/" and u or ("/" .. u))
    end
    return u
end

-- RFC 3986 merge, mirroring java.net.URI(base):resolve(href) — the exact
-- semantics of the engine global url_resolve (plugin-tester-jvm
-- LuaEngineCli.kt:355). Used only when that global is unavailable
-- (offline tests); in the app the global always wins.
local function removeDotSegments(p)
    local leading = p:sub(1, 1) == "/"
    local segs = {}
    for seg in p:gmatch("[^/]+") do
        if seg == ".." then
            if #segs > 0 and segs[#segs] ~= ".." then
                segs[#segs] = nil
            elseif not leading then
                segs[#segs + 1] = seg
            end
        elseif seg ~= "." then
            segs[#segs + 1] = seg
        end
    end
    local out = table.concat(segs, "/")
    if leading then out = "/" .. out end
    if p:sub(-1) == "/" and out:sub(-1) ~= "/" then out = out .. "/" end
    return out
end

local function splitRef(u)
    local path, query, fragment = u, "", ""
    local hash = path:find("#", 1, true)
    if hash then fragment = path:sub(hash + 1) path = path:sub(1, hash - 1) end
    local qm = path:find("?", 1, true)
    if qm then query = path:sub(qm + 1) path = path:sub(1, qm - 1) end
    return path, query, fragment
end

local function resolveRef(base, ref)
    if type(base) ~= "string" or type(ref) ~= "string" then return ref end
    if ref:match("^%a[%w+.-]*:") then return ref end
    local scheme, authority, rest = base:match("^(%a[%w+.-]*)://([^/?#]*)(.*)$")
    if not scheme then return ref end
    if ref:sub(1, 2) == "//" then return scheme .. "://" .. ref:sub(3) end
    local rPath, rQuery, rFrag = splitRef(ref)
    local bPath, bQuery = splitRef(rest)
    local path, query
    if rPath == "" then
        path = bPath
        query = (rQuery ~= "") and rQuery or bQuery
    elseif rPath:sub(1, 1) == "/" then
        path = rPath
        query = rQuery
    else
        path = (bPath:match("^.*/") or "/") .. rPath
        query = rQuery
    end
    local out = scheme .. "://" .. authority .. removeDotSegments(path)
    if query ~= "" then out = out .. "?" .. query end
    if rFrag ~= "" then out = out .. "#" .. rFrag end
    return out
end

-- href found in a page -> absolute URL, relative to `base` (usually baseUrl).
-- Union of the two inline variants: the dominant url_resolve one (guide:1763,
-- 36 byte-identical copies, e.g. ru/ranobehub.lua:11) and the manual sub/find
-- one (es/latanime.lua:94, en/hianimes.lua:50, id/anichin.lua:70). They agree
-- on absolute / protocol-relative / root-relative hrefs; for a bare relative
-- href the canonical url_resolve merge (RFC 3986) is used, the manual copies
-- joined it as baseDir .. "/" .. href — plugins relying on that join must be
-- checked during migration. Empty or non-string href -> "" (guide template).
function M.absUrl(base, href)
    if type(href) ~= "string" or href == "" then return "" end
    if href:sub(1, 4) == "http" then return href end
    if href:sub(1, 2) == "//" then return "https:" .. href end
    if type(url_resolve) == "function" then return url_resolve(base, href) end
    return resolveRef(base, href)
end

-- Google Drive file page -> direct usercontent download URL, no network:
-- the file id lives in the link itself (checked live 2026-10-03, usercontent
-- with confirm=t answers 206 without a single header).
-- Merged from the four inline copies: ar/anime4up.lua:813, ar/witanime.lua:1423,
-- ar/animephoenix.lua:698, es/latanime.lua:280 — all equivalent; the union keeps
-- the nil-safe host match (anime4up dereferenced match() without `or ""`).
-- ponytail: no playback-API fallback for "download disabled" (403 + UA binding) —
-- add it when locked links actually show up on the sites.
function M.driveDirectUrl(link)
    if type(link) ~= "string" then return nil end
    local host = (link:match("^https?://([^/]+)") or ""):lower()
    host = host:gsub("^www%.", "")
    if host ~= "drive.google.com" and host ~= "drive.usercontent.google.com" then
        return nil
    end
    local id = link:match("/file/d/([%w_-]+)") or link:match("[?&]id=([%w_-]+)")
    if not id then return nil end
    local u = "https://drive.usercontent.google.com/download?id=" .. id
        .. "&export=download&confirm=t"
    local rk = link:match("[?&]resourcekey=([%w_-]+)")
    if rk then u = u .. "&resourcekey=" .. rk end
    return u
end

return M
end

require_lib = function(id)
    local cached = rawget(__LIBS, id)
    if cached ~= nil then return cached end
    local loader = rawget(__LOADERS, id)
    if loader == nil then error("bundle_libs: unknown library id: " .. tostring(id), 2) end
    local value = loader()
    __LIBS[id] = value
    return value
end
-- END BUNDLED LIBRARIES (tools/bundle_libs.py)
-- AnimePhoenix — видео-плагин Dreamora (content_type = "video")
-- Сайт: https://anime-phoenix.com — каталог аниме/фильмов, эпизоды, серверы плеера.

content_type = "video"
id           = "animephoenix"
name         = "Anime Phoenix"
version      = "1.1.1"
baseUrl      = "https://anime-phoenix.com"
language = {"ar", "en"}
icon         = "https://raw.githubusercontent.com/Stlucifer15t/external-sources/refs/heads/main/icons/animephoenix.png"

local floor = math.floor

-- ============ Guard: engine-API + общие либы (новые сборки Dreamora) ============
-- Top-level обязан загрузиться без require_lib (иначе плагин молча исчезает из
-- списка источников) — pcall-tryLib-паттерн latanime (M9): ошибка сохраняется
-- в libErr и докладывается в ensureEngine.
local libErr = nil
local HAS_LIBS = type(require_lib) == "function"

local function tryLib(name)
    if not HAS_LIBS then return nil end
    local ok, res = pcall(require_lib, name)
    if not ok then libErr = tostring(res) return nil end
    return res
end

local URLS = tryLib("urls")
local FETCH = tryLib("fetch")
local CATALOG = tryLib("catalog")
local SOURCES = tryLib("sources")
local HLS = tryLib("hls")
local OKRU = tryLib("okru")
local SHARED = tryLib("shared")
local UQLOAD = tryLib("uqload")

-- Канон (гайд «Паттерн guard»): проверяем только реально используемые API.
-- На старых сборках show_error + error рвут вызов и просят обновить приложение.
local function ensureEngine()
    local missing = {}
    if rawget(_G, "hmac_sha256") == nil then missing[#missing + 1] = "hmac_sha256" end
    if rawget(_G, "unpack_packed") == nil then missing[#missing + 1] = "unpack_packed" end
    if #missing > 0 then
        show_error("Dreamora update required",
            "This plugin needs new functions (" .. table.concat(missing, ", ") ..
            "). Update the app to the latest version.")
        error("A newer version of the app is required: " .. table.concat(missing, ","), 0)
    end
    if not HAS_LIBS then
        show_error("Dreamora update required",
            "This plugin needs shared libraries (require_lib). Update the app to the latest version.")
        error("A newer version of the app is required: require_lib", 0)
    end
    if not URLS or not FETCH or not CATALOG or not SOURCES
        or not HLS or not OKRU or not SHARED or not UQLOAD then
        show_error("Libraries not loaded",
            "Open the extensions screen and tap update, then restart the app. " .. (libErr or ""))
        error("Shared libraries not loaded", 0)
    end
end

-- ============ Утилиты ============

local function absUrl(href) return URLS.absUrl(baseUrl, href) end

-- Безопасное число из JSON-значения: number | строка | иначе nil.
local function toNumber(v)
    if type(v) == "number" then return v end
    if type(v) == "string" then return tonumber(v) end
    return nil
end

-- Кэш страницы тайтла ведёт общий fetch lib: title/cover/description/
-- genres/rating/status — 6 вызовов на одну страницу.
local function fetchPage(url) return FETCH.page(url) end

-- Есть ли медиа-расширение в конце пути URL (до "?" / "#").
-- Общая либа hls (union копий, включая .mkv из этого плагина).
-- Обёртка, не алиас: top-level обращение к полю nil-либы упало бы до
-- ensureEngine (плагин молча исчезает — инцидент фазы 1).
local function hasMediaExt(u)
    return HLS.hasMediaExt(u)
end

-- Percent-декод пути URL для разбора имени файла: часть зеркал отдаёт ссылку
-- с %20, часть — с двойным %2520. Без декода qualityFromUrl матчил «20» из
-- «%20» и в подпись источника попадало «201080p» (баг 2026-10-03).
local function decodeUrlPath(u)
    local base = u:match("^[^%?#]*") or u
    for _ = 1, 2 do
        base = base:gsub("%%(%x%x)", function(hex)
            return string.char(tonumber(hex, 16))
        end)
    end
    return base
end

-- Подпись качества для UI: "1080p" из имени файла в URL; нет паттерна → nil.
-- Кандидаты с неправдоподобным разрешением («201080p» и т.п.) пропускаются.
local function qualityFromUrl(u)
    for m in decodeUrlPath(u):gmatch("(%d+p)") do
        local n = tonumber(m:match("%d+"))
        if n and n >= 144 and n <= 4320 then return m end
    end
    return nil
end

-- Подпись источника: «<имя сервера> · <разрешение> · <языка/озвучка>».
-- Имя — из data-server JSON, разрешение и язык — из имени файла в URL
-- ([WebDL - 1080p - Ar - x265]). Всё, что не распознано, просто не
-- попадает в подпись; никаких догадок.
local function sourceLabel(name, u)
    local parts = {}
    if type(name) == "string" and name ~= "" then parts[#parts + 1] = name end
    local q = qualityFromUrl(u)
    if q then parts[#parts + 1] = q end
    -- ищем токен сразу после «<разрешение> - »: «1080p - Ar - x265»
    local s = decodeUrlPath(u)
    local lang = s:match("%d+p%s*%-%s*([%a][%w]*)%s*%-%s*x%d%d")
        or s:match("%d+p%s*%-%s*([%a][%w]*)%s*%]")
    if lang and lang ~= q then parts[#parts + 1] = lang end
    return table.concat(parts, " · ")
end

-- Hex вручную: string.format на этом движке игнорирует спецификаторы (гайд).
local HEX_DIGITS = "0123456789abcdef"

local function hexEncode(raw)
    local t = {}
    for i = 1, #raw do
        local b = string.byte(raw, i)
        local hi, lo = floor(b / 16), b % 16
        t[i] = HEX_DIGITS:sub(hi + 1, hi + 1) .. HEX_DIGITS:sub(lo + 1, lo + 1)
    end
    return table.concat(t)
end

-- ============ Каталог / поиск: api/search.php ============
-- Старые пути мертвы (живая проверка 2026-10-03): /search?type=tvshow&sort=views
-- отдаёт 0 карточек, admin-ajax action=phoenix_search — пусто. Работает только
-- GET /api/search.php с подписью HMAC-SHA256 и заголовками X-PX-*.

-- PhoenixSearch.public_key из инлайн-скрипта
-- phoenix-search-dropdown-script-js-extra: hex-строка идёт в HMAC КАК UTF-8
-- байты (как JS enc.encode(keyHex)), НЕ hex-decode. Публичный ключ → хардкод.
local PX_PUBLIC_KEY = "c8052e98457156515d839dd050a95ac1b862437995778d89422a45f117478009"

local function emptyCatalog()
    return { items = {}, hasNext = false }
end

-- Целое число в строку без научной нотации: tostring() на этом движке
-- даёт «1.7910077E9» вместо «1791007748», подпись становится невалидной.
local function intToStr(n)
    n = math.floor(n)
    if n < 0 then return "-" .. intToStr(-n) end
    if n < 10 then return string.char(48 + n) end
    return intToStr(math.floor(n / 10)) .. string.char(48 + n % 10)
end

-- GET api/search.php → {items, hasNext}. Канон подписи (9 полей через «:»):
--   ts:q:type:genre:status:year:season:page:sort
-- и обязан ТОЧНО совпадать со значениями в URL. TTL подписи 60–119 с —
-- подпись считается непосредственно перед запросом, os.time() в секундах.
-- Порядок и состав параметров URL менять нельзя: живой прогон 2026-10-03
-- прошёл только с этим каноном (порядок из search-page.js), сама же JS
-- в браузере чужой порядок/лишний параметр даёт total:0 — фильтруем
-- только значения, не конфигурацию запроса.
local function apiCatalog(q, ctype, status, sort, page)
    q = q or ""
    ctype = ctype or "tvshow"
    status = status or ""
    sort = sort or "views"
    page = page or 1

    local ts = os.time()
    local tsStr = intToStr(ts)
    local msg = table.concat(
        { tsStr, q, ctype, "", status, "", "", tostring(page), sort }, ":")
    local sig = hexEncode(hmac_sha256(PX_PUBLIC_KEY, msg))

    local url = baseUrl .. "/api/search.php"
        .. "?type=" .. CATALOG.urlEncode(ctype)
        .. "&genre=&status=" .. CATALOG.urlEncode(status) .. "&year=&season="
        .. "&sort=" .. CATALOG.urlEncode(sort)
        .. "&q=" .. CATALOG.urlEncode(q)
        .. "&page=" .. tostring(page)
        .. "&per_page=25&dropdown=0"
        -- "_" — обязательный cache-bust: без него CF-кеш отдаёт чужой ответ.
        .. "&_=" .. tsStr .. tostring(math.random(1000, 9999))

    -- Referer обязателен (без него запрос не проходит — замерено).
    local r = http_get(url, {
        headers = {
            ["X-PX-Timestamp"] = tsStr,
            ["X-PX-Signature"] = sig,
            ["Referer"]        = baseUrl .. "/search/",
        },
    })
    if not r.success then
        log_error("AnimePhoenix: api/search.php — HTTP " .. tostring(r.code))
        return emptyCatalog()
    end

    local ok, data = pcall(json_parse, r.body)
    if not ok or type(data) ~= "table" or not data.success then
        log_error("AnimePhoenix: api/search.php — битый ответ")
        return emptyCatalog()
    end
    local d = type(data.data) == "table" and data.data or nil
    local results = d and type(d.results) == "table" and d.results or nil
    if not results then
        log_error("AnimePhoenix: api/search.php — нет data.results")
        return emptyCatalog()
    end

    local items = {}
    for _, it in ipairs(results) do
        if type(it) == "table" then
            local title = it.title_ar
            if type(title) ~= "string" or title == "" then title = it.title_en end
            local u = type(it.url) == "string" and it.url or ""
            if type(title) == "string" and title ~= "" and u ~= "" then
                local cover = type(it.thumbnail_url) == "string" and it.thumbnail_url or ""
                items[#items + 1] = {
                    title = string_clean(title),
                    url   = absUrl(u),
                    cover = cover ~= "" and absUrl(cover) or nil,
                }
            end
        end
    end

    local totalPages = toNumber(d.total_pages) or 0
    local hasNext = CATALOG.hasNextPage(items)
    if totalPages > 0 then hasNext = page < totalPages end
    return { items = items, hasNext = hasNext }
end

function getCatalogList(index)
    ensureEngine()
    return apiCatalog("", "tvshow", "", "views", CATALOG.nextIndex(index))
end

